import React, { useState, useRef, useEffect, useCallback } from 'react';
import axios from 'axios';

const COLORS = {
  primary: '#3B82F6',
  success: '#10B981',
  error: '#EF4444',
  gray: '#64748B',
  lightGray: '#F1F5F9',
  placeholder: '#9CA3AF',
};

const CameraRecognition = ({ addNotification }) => {
  const videoRef = useRef(null);
  const canvasRef = useRef(null);
  const streamRef = useRef(null);
  const captureIntervalRef = useRef(null);
  const audioContextRef = useRef(null);

  const [loading, setLoading] = useState(false);
  const [status, setStatus] = useState('idle'); // idle | scanning | success | error
  const [result, setResult] = useState(null);
  const [capturedImage, setCapturedImage] = useState(null);
  const [registeredPhotoUrl, setRegisteredPhotoUrl] = useState(null);
  const [faceBox, setFaceBox] = useState(null);

  const [autoMode, setAutoMode] = useState(true);
  const [frameCount, setFrameCount] = useState(0);
  const [scanAttempts, setScanAttempts] = useState(0);
  const [successCount, setSuccessCount] = useState(0);
  const [errorCount, setErrorCount] = useState(0);
  const [lastDetection, setLastDetection] = useState(null);
  const [errorMsg, setErrorMsg] = useState(null);

  // Sons de feedback
  const playSound = useCallback((type) => {
    try {
      if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || window.webkitAudioContext)();
      }
      const ctx = audioContextRef.current;
      const oscillator = ctx.createOscillator();
      const gain = ctx.createGain();

      if (type === 'success') {
        oscillator.type = 'sine';
        oscillator.frequency.setValueAtTime(750, ctx.currentTime);
        setTimeout(() => oscillator.frequency.setValueAtTime(1100, ctx.currentTime + 0.08), 70);
        gain.gain.value = 0.25;
      } else {
        oscillator.type = 'sawtooth';
        oscillator.frequency.setValueAtTime(380, ctx.currentTime);
        gain.gain.value = 0.18;
      }

      const filter = ctx.createBiquadFilter();
      filter.type = 'lowpass';
      filter.frequency.value = 1800;

      oscillator.connect(filter);
      filter.connect(gain);
      gain.connect(ctx.destination);

      oscillator.start();
      setTimeout(() => {
        gain.gain.linearRampToValueAtTime(0.001, ctx.currentTime + 0.35);
        oscillator.stop(ctx.currentTime + 0.45);
      }, type === 'success' ? 300 : 200);
    } catch (e) {
      console.warn('Son non joué:', e);
    }
  }, []);

  // Démarrage de la caméra
  useEffect(() => {
    const startCamera = async () => {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({
          video: { facingMode: 'user', width: { ideal: 1280 }, height: { ideal: 720 } },
          audio: false,
        });
        streamRef.current = stream;
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
        }
      } catch (err) {
        console.error('Erreur caméra:', err);
        setErrorMsg("Impossible d'accéder à la caméra");
        addNotification("❌ Erreur d'accès à la caméra", 'error');
      }
    };

    startCamera();

    return () => {
      if (captureIntervalRef.current) clearInterval(captureIntervalRef.current);
      if (streamRef.current) {
        streamRef.current.getTracks().forEach(track => track.stop());
      }
    };
  }, [addNotification]);

  // Mode Auto - Capture continue
  useEffect(() => {
    if (!autoMode) {
      if (captureIntervalRef.current) clearInterval(captureIntervalRef.current);
      setStatus('idle');
      return;
    }

    setStatus('scanning');
    setErrorMsg(null);

    captureIntervalRef.current = setInterval(async () => {
      if (!videoRef.current || loading) return;

      try {
        const canvas = document.createElement('canvas');
        canvas.width = videoRef.current.videoWidth || 1280;
        canvas.height = videoRef.current.videoHeight || 720;
        const ctx = canvas.getContext('2d');
        ctx.drawImage(videoRef.current, 0, 0);

        const imageBase64 = canvas.toDataURL('image/jpeg', 0.85);

        setLoading(true);
        setFrameCount(prev => prev + 1);
        setScanAttempts(prev => prev + 1);

        const response = await axios.post('/api/recognize/', {
          image: imageBase64.split(',')[1],
        });

        const data = response.data;

        if (data.face_box) setFaceBox(data.face_box);

        if (data.success && data.student) {
          setResult(data);
          setCapturedImage(imageBase64);
          setRegisteredPhotoUrl(data.registered_photo_url || null);
          setLastDetection(new Date().toLocaleTimeString());
          setStatus('success');
          setSuccessCount(prev => prev + 1);

          playSound('success');
          addNotification(`✅ ${data.student} marqué présent`, 'success');

          setAutoMode(false);
          setTimeout(() => setAutoMode(true), 4000);
        } else {
          setStatus('error');
          setErrorMsg(data.message || "Visage non reconnu");
          setErrorCount(prev => prev + 1);
          playSound('error');
        }
      } catch (err) {
        const msg = err.response?.data?.message || err.message || "Erreur serveur";
        setErrorMsg(msg);
        setStatus('error');
        setErrorCount(prev => prev + 1);
        playSound('error');
        addNotification(`❌ ${msg}`, 'error');
      } finally {
        setLoading(false);
      }
    }, 800); // ← Changé à 800ms comme demandé

    return () => {
      if (captureIntervalRef.current) clearInterval(captureIntervalRef.current);
    };
  }, [autoMode, loading, addNotification, playSound]);

  // Capture manuelle
  const handleManualCapture = async () => {
    if (!videoRef.current || loading) return;

    setLoading(true);
    setErrorMsg(null);
    setResult(null);
    setFaceBox(null);

    try {
      const canvas = document.createElement('canvas');
      canvas.width = videoRef.current.videoWidth || 1280;
      canvas.height = videoRef.current.videoHeight || 720;
      const ctx = canvas.getContext('2d');
      ctx.drawImage(videoRef.current, 0, 0);

      const imageBase64 = canvas.toDataURL('image/jpeg', 0.9);
      setCapturedImage(imageBase64);

      const response = await axios.post('/api/recognize/', {
        image: imageBase64.split(',')[1],
      });

      const data = response.data;

      if (data.success && data.student) {
        setResult(data);
        setRegisteredPhotoUrl(data.registered_photo_url);
        setStatus('success');
        setLastDetection(new Date().toLocaleTimeString());
        setSuccessCount(prev => prev + 1);
        playSound('success');
        addNotification(`✅ ${data.student} marqué présent`, 'success');
      } else {
        setStatus('error');
        setErrorMsg(data.message || "Visage non reconnu");
        setErrorCount(prev => prev + 1);
        playSound('error');
      }
    } catch (err) {
      const msg = err.response?.data?.message || "Erreur de reconnaissance";
      setErrorMsg(msg);
      setStatus('error');
      setErrorCount(prev => prev + 1);
      playSound('error');
      addNotification(`❌ ${msg}`, 'error');
    } finally {
      setLoading(false);
    }
  };

  const stopCamera = () => {
    if (captureIntervalRef.current) clearInterval(captureIntervalRef.current);
    if (streamRef.current) streamRef.current.getTracks().forEach(track => track.stop());
    if (videoRef.current) videoRef.current.srcObject = null;
    setAutoMode(false);
    setStatus('idle');
    setFaceBox(null);
  };

  // Placeholder pour photo enregistrée
  const RegisteredPhoto = () => {
    if (registeredPhotoUrl) {
      return <img src={registeredPhotoUrl} alt="Photo enregistrée" style={styles.photo} />;
    }
    return (
      <div style={styles.placeholder}>
        <div style={styles.silhouette}>👤</div>
        <p style={{ margin: '8px 0 0 0', color: '#6B7280', fontSize: '0.9rem' }}>
          Photo de référence
        </p>
      </div>
    );
  };

  return (
    <div style={styles.container}>
      <h1 style={styles.title}>👤 Reconnaissance Faciale - Présence</h1>

      <div style={styles.videoWrapper}>
        <div style={styles.videoContainer}>
          <video
            ref={videoRef}
            autoPlay
            playsInline
            muted
            style={styles.video}
            aria-label="Flux vidéo en direct de la caméra"
          />
          <canvas ref={canvasRef} style={styles.overlayCanvas} />

          <div style={{
            ...styles.statusBadge,
            backgroundColor: status === 'success' ? COLORS.success :
                            status === 'error' ? COLORS.error :
                            autoMode ? '#10B981' : COLORS.gray
          }}>
            {status === 'success' ? '✅ Reconnu' :
             status === 'error' ? '❌ Échec' :
             autoMode ? '🔄 Scanning...' : '⏸️ Pause'}
          </div>
        </div>
      </div>

      <div style={styles.actions}>
        <button
          onClick={handleManualCapture}
          disabled={loading}
          style={styles.btnPrimary}
          aria-label="Capturer maintenant"
        >
          {loading ? '⏳ Traitement...' : '📸 Capturer maintenant'}
        </button>

        <button
          onClick={() => setAutoMode(!autoMode)}
          style={{ ...styles.btn, backgroundColor: autoMode ? COLORS.error : '#6366F1' }}
          aria-label={autoMode ? "Arrêter le mode automatique" : "Démarrer le mode automatique"}
        >
          {autoMode ? '⏹ Arrêter Auto' : '▶️ Démarrer Auto'}
        </button>

        <button
          onClick={stopCamera}
          style={styles.btnDanger}
          aria-label="Fermer la caméra"
        >
          🛑 Fermer Caméra
        </button>
      </div>

      {/* Comparaison des photos */}
      {(capturedImage || result) && (
        <div style={styles.comparisonContainer}>
          <div style={styles.photoPair}>
            <div>
              <p style={styles.photoLabel}>📸 Photo capturée</p>
              {capturedImage ? (
                <img src={capturedImage} alt="Capture caméra" style={styles.photo} />
              ) : (
                <div style={styles.noCapture}>Aucune capture disponible</div>
              )}
            </div>

            <div>
              <p style={styles.photoLabel}>📁 Photo enregistrée</p>
              <RegisteredPhoto />
            </div>
          </div>
        </div>
      )}

      {/* Résultat succès avec animation */}
      {result && result.success && (
        <div style={styles.successBox}>
          <h3>✅ {result.student} marqué présent</h3>
          <p><strong>Email :</strong> {result.email || 'Non renseigné'}</p>
          <p><strong>Confiance :</strong> {(result.confidence * 100).toFixed(1)}%</p>
          <p><strong>ID Présence :</strong> {result.attendance_id}</p>
          <p><strong>Heure :</strong> {lastDetection}</p>
        </div>
      )}

      {/* Message d'erreur avec animation */}
      {errorMsg && (
        <div style={styles.errorBox}>
          ❌ {errorMsg}
        </div>
      )}

      {/* Statistiques */}
      <div style={styles.statsGrid}>
        <div>Dernière détection : <strong>{lastDetection || '—'}</strong></div>
        <div>Succès : <strong style={{ color: COLORS.success }}>{successCount}</strong></div>
        <div>Échecs : <strong style={{ color: COLORS.error }}>{errorCount}</strong></div>
        <div>Taux de précision : <strong>{successCount + errorCount > 0 
          ? ((successCount / (successCount + errorCount)) * 100).toFixed(1) 
          : 0}%</strong></div>
      </div>

      {/* Debug */}
      <div style={styles.debug}>
        Mode Auto : {autoMode ? 'ON' : 'OFF'} | 
        Frames : {frameCount} | 
        Tentatives : {scanAttempts} | 
        Status : {status} | 
        En cours : {loading ? 'Oui' : 'Non'}
      </div>
    </div>
  );
};

const styles = {
  container: { 
    padding: '30px', 
    maxWidth: '1050px', 
    margin: '0 auto', 
    fontFamily: 'system-ui, -apple-system, Arial, sans-serif' 
  },
  title: { 
    textAlign: 'center', 
    fontSize: '1.85rem', 
    marginBottom: '28px', 
    color: '#1E2937' 
  },

  videoWrapper: { position: 'relative', marginBottom: '28px' },
  videoContainer: { 
    position: 'relative', 
    borderRadius: '16px', 
    overflow: 'hidden', 
    boxShadow: '0 10px 30px rgba(0,0,0,0.25)', 
    background: '#000' 
  },
  video: { width: '100%', display: 'block' },
  overlayCanvas: { 
    position: 'absolute', 
    top: 0, 
    left: 0, 
    width: '100%', 
    height: '100%', 
    pointerEvents: 'none' 
  },

  statusBadge: {
    position: 'absolute',
    top: '18px',
    right: '18px',
    color: 'white',
    padding: '10px 20px',
    borderRadius: '9999px',
    fontWeight: 'bold',
    boxShadow: '0 4px 12px rgba(0,0,0,0.3)'
  },

  actions: { 
    display: 'flex', 
    gap: '14px', 
    flexWrap: 'wrap', 
    marginBottom: '30px' 
  },
  btn: { 
    flex: 1, 
    padding: '16px', 
    border: 'none', 
    borderRadius: '12px', 
    color: 'white', 
    fontWeight: '600', 
    cursor: 'pointer', 
    fontSize: '1.02rem',
    transition: 'all 0.2s'
  },
  btnPrimary: { 
    flex: 1, 
    padding: '16px', 
    backgroundColor: COLORS.primary, 
    border: 'none', 
    borderRadius: '12px', 
    color: 'white', 
    fontWeight: '600', 
    cursor: 'pointer', 
    fontSize: '1.02rem' 
  },
  btnDanger: { 
    flex: 1, 
    padding: '16px', 
    backgroundColor: '#475569', 
    border: 'none', 
    borderRadius: '12px', 
    color: 'white', 
    fontWeight: '600', 
    cursor: 'pointer', 
    fontSize: '1.02rem' 
  },

  comparisonContainer: { margin: '30px 0' },
  photoPair: { 
    display: 'grid', 
    gridTemplateColumns: '1fr 1fr', 
    gap: '24px' 
  },
  photoLabel: { 
    textAlign: 'center', 
    marginBottom: '10px', 
    fontWeight: '500', 
    color: '#374151' 
  },
  photo: { 
    width: '100%', 
    borderRadius: '12px', 
    border: '3px solid #E2E8F0',
    boxShadow: '0 4px 12px rgba(0,0,0,0.1)'
  },
  placeholder: {
    width: '100%',
    height: '280px',
    backgroundColor: '#F3F4F6',
    borderRadius: '12px',
    border: '3px dashed #9CA3AF',
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'center',
    justifyContent: 'center',
    color: COLORS.placeholder
  },
  silhouette: {
    fontSize: '4.5rem',
    opacity: 0.6
  },
  noCapture: {
    width: '100%',
    height: '280px',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    backgroundColor: '#F8FAFC',
    border: '3px dashed #CBD5E1',
    borderRadius: '12px',
    color: '#64748B',
    fontStyle: 'italic'
  },

  successBox: {
    animation: 'fadeIn 0.4s ease-in',
    background: '#F0FDF4',
    borderLeft: `6px solid ${COLORS.success}`,
    padding: '22px',
    borderRadius: '12px',
    margin: '25px 0'
  },
  errorBox: {
    animation: 'fadeIn 0.4s ease-in',
    background: '#FEF2F2',
    borderLeft: `6px solid ${COLORS.error}`,
    padding: '20px',
    borderRadius: '12px',
    color: '#991B1B',
    margin: '20px 0'
  },

  statsGrid: {
    display: 'grid',
    gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))',
    gap: '14px',
    margin: '30px 0',
    fontSize: '1rem'
  },

  debug: {
    background: '#F8FAFC',
    padding: '14px 18px',
    borderRadius: '10px',
    fontSize: '0.87rem',
    color: '#64748B',
    borderLeft: '5px solid #94A3B8',
    marginTop: '20px'
  }
};

// Animation fade-in
const style = document.createElement('style');
style.textContent = `
  @keyframes fadeIn {
    from { opacity: 0; transform: translateY(10px); }
    to { opacity: 1; transform: translateY(0); }
  }
`;
document.head.appendChild(style);

export default CameraRecognition;
